/**
 * @goat/bridge-mock - Master Type Definitions
 * Complete TypeScript interfaces matching Android (Kotlin), iOS (Swift), and miniapp-bridge.
 */

export interface BridgeRequest<T = Record<string, any>> {
  /** Unique correlation ID generated by the client */
  id: string;
  /** Action identifier string matching one of the 197 supported action names */
  action: string;
  /** Strongly-typed dictionary of input arguments */
  payload?: T;
  /** Alias for payload */
  params?: T;
}

export interface BridgeResponse<T = unknown> {
  /** Corresponding request correlation ID */
  id: string;
  /** Whether the native handler executed successfully */
  success: boolean;
  /** Response payload returned upon success */
  data?: T;
  /** Error message or code returned upon failure */
  error?: string;
  /** Status code (e.g. 200, 400, 403, 404, 500) */
  code?: number;
}

